    for (let index = numberStack.length - 1; index >= 0; index--) {
      // 从部分和中减去栈中的元素
      partialSum -= numberStack[index];

      // 如果满足出栈条件，清除子列表并更新当前数字
      if (partialSum === 0) {
        // 清除子列表
        numberStack.splice(index);
        // 更新当前数字
