#include <stdio.h>
#include <stdlib.h>
#include <string.h>

// 定义一个栈结构体，用于存储整数
typedef struct {
    int *data;      // 栈中存储的数据
    int top;        // 栈顶索引
    int capacity;   // 栈的容量
} Stack;

// 初始化栈，分配内存并设置初始值
Stack* createStack(int capacity) {
    Stack *stack = (Stack*)malloc(sizeof(Stack));
    stack->data = (int*)malloc(capacity * sizeof(int));
    stack->top = -1;   // 初始化栈顶索引为-1，表示空栈
    stack->capacity = capacity;
    return stack;
}

// 判断栈是否为空
int isEmpty(Stack *stack) {
    return stack->top == -1;
}

// 向栈中压入元素
void push(Stack *stack, int value) {
    stack->data[++stack->top] = value;
}

// 从栈中弹出元素
int pop(Stack *stack) {
    return stack->data[stack->top--];
}

// 返回栈顶元素但不弹出
int peek(Stack *stack) {
    return stack->data[stack->top];
}

// 释放栈的内存
void freeStack(Stack *stack) {
    free(stack->data);
    free(stack);
}

// 主函数，负责处理输入输出和逻辑
int main() {
    char input[10000]; // 存储输入字符串
    fgets(input, sizeof(input), stdin); // 读取输入字符串

    // 初始化栈，容量设为1000
    Stack *stack = createStack(1000);

    // 解析输入的整数序列
    char *token = strtok(input, " ");
    while (token != NULL) {
        int currentNumber = atoi(token);  // 将当前字符串转换为整数
        int partialSum = currentNumber;   // 初始化部分和为当前数字

        // 从栈顶向栈底检查是否满足出栈条件
        for (int index = stack->top; index >= 0; index--) {
            partialSum -= stack->data[index]; // 从部分和中减去栈中的元素

            // 如果满足出栈条件，清除子列表并更新当前数字
            if (partialSum == 0) {
                stack->top = index - 1;  // 调整栈顶位置以清除子列表
                currentNumber *= 2;      // 更新当前数字为原数字的2倍
                partialSum = currentNumber; // 更新部分和
            } else if (partialSum < 0) {
                // 如果部分和小于0，跳出循环
                break;
            }
        }

        // 将当前数字压入栈中
        push(stack, currentNumber);

        // 获取下一个输入的整数
        token = strtok(NULL, " ");
    }

    // 输出栈中的元素，从栈顶到栈底
    int first = 1; // 用于控制输出格式
    while (!isEmpty(stack)) {
        if (!first) {
            printf(" "); // 在元素之间输出空格
        }
        printf("%d", pop(stack)); // 输出栈顶元素
        first = 0;
    }
    printf("\n"); // 输出换行符

    // 释放栈的内存
    freeStack(stack);

    return 0;
}

